CREATE TABLE local_scope(singleton INTEGER PRIMARY KEY CHECK(singleton=1), company_id TEXT NOT NULL,user_id TEXT NOT NULL,device_id TEXT NOT NULL);
CREATE TABLE drafts(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('receipt','expense-request')),currency TEXT NOT NULL CHECK(currency IN('CDF','USD')),amount TEXT NOT NULL,description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 500),version INTEGER NOT NULL CHECK(version>0),state TEXT NOT NULL CHECK(state IN('local','synced','conflict','error')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,CHECK(expires_at>created_at AND expires_at-created_at<=900000));
CREATE TABLE sync_metadata(draft_id TEXT PRIMARY KEY REFERENCES drafts(id) ON DELETE CASCADE,idempotency_key TEXT UNIQUE NOT NULL CHECK(idempotency_key=draft_id),last_attempt_at INTEGER,last_attempt_version INTEGER,server_version INTEGER,result_code TEXT CHECK(result_code IN('draft-received','conflict','validation-failed','offline','transport-error')));
CREATE TABLE authorized_cache(resource_id TEXT PRIMARY KEY,permission TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),version INTEGER NOT NULL CHECK(version>0),schema_version INTEGER NOT NULL CHECK(schema_version=1),synchronized_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,authorized_until INTEGER NOT NULL,CHECK(expires_at>synchronized_at AND expires_at-synchronized_at<=900000 AND expires_at<=authorized_until));
CREATE TRIGGER draft_identity BEFORE UPDATE ON drafts WHEN NEW.id<>OLD.id OR NEW.kind<>OLD.kind OR NEW.created_at<>OLD.created_at OR NEW.expires_at<>OLD.expires_at BEGIN SELECT RAISE(ABORT,'LOCAL_IDENTITY_IMMUTABLE'); END;
